<?php
$page_title='Kiểm tra';
require_once 'includes/functions.php';
require_login();

function fc_norm($value): string {$value=preg_replace('/\s+/u',' ',trim((string)$value));return function_exists('mb_strtolower')?mb_strtolower($value,'UTF-8'):strtolower($value);}
function fc_is_leader(array $user): bool {return ($user['role']??'')==='totruong'||in_array('totruong',(array)($user['groups']??[]),true);}
function fc_teacher_id($name): string {foreach(load_json(dirname(__DIR__).'/data/teachers.json',[]) as $teacher)if(fc_norm($teacher['name']??'')===fc_norm($name))return(string)($teacher['id']??'');return '';}
function fc_criteria(): array {$saved=load_json(dirname(__DIR__).'/data/teacher_evaluation_config.json',[]);$rows=$saved['criteria']??[];if(!$rows)$rows=[['id'=>'obs_good','name'=>'Dự giờ xếp loại Tốt','group_id'=>'professional','operation'=>'add','points'=>5],['id'=>'obs_fair','name'=>'Dự giờ xếp loại Khá','group_id'=>'professional','operation'=>'add','points'=>3],['id'=>'obs_pass','name'=>'Dự giờ xếp loại Đạt','group_id'=>'professional','operation'=>'add','points'=>1],['id'=>'file_good','name'=>'Hồ sơ xếp loại Tốt','group_id'=>'professional','operation'=>'add','points'=>5],['id'=>'file_fair','name'=>'Hồ sơ xếp loại Khá','group_id'=>'professional','operation'=>'add','points'=>3],['id'=>'file_pass','name'=>'Hồ sơ xếp loại Đạt','group_id'=>'professional','operation'=>'add','points'=>1],['id'=>'attendance_base','name'=>'Điểm ngày công ban đầu','group_id'=>'attendance','operation'=>'add','points'=>30],['id'=>'absence_unpermitted','name'=>'Nghỉ không phép','group_id'=>'attendance','operation'=>'subtract','points'=>2],['id'=>'absence_permitted','name'=>'Nghỉ có phép','group_id'=>'attendance','operation'=>'subtract','points'=>0],['id'=>'late','name'=>'Đi muộn','group_id'=>'attendance','operation'=>'subtract','points'=>.5],['id'=>'ach_school','name'=>'Thành tích cấp Trường','group_id'=>'achievement','operation'=>'add','points'=>2],['id'=>'ach_district','name'=>'Thành tích cấp Huyện','group_id'=>'achievement','operation'=>'add','points'=>4],['id'=>'ach_province','name'=>'Thành tích cấp Tỉnh','group_id'=>'achievement','operation'=>'add','points'=>7],['id'=>'ach_national','name'=>'Thành tích cấp Quốc gia','group_id'=>'achievement','operation'=>'add','points'=>10]];return array_values(array_filter($rows,fn($row)=>!empty($row['id'])&&!empty($row['name'])));}
function fc_outcome(array $row,array $criteriaById): string {if(($row['content_type']??'file')==='file')return(string)($row['rating']??'');$criterion=$criteriaById[(string)($row['criterion_id']??'')]??[];return ($criterion['operation']??($row['operation']??'add'))==='subtract'?'Điểm trừ':'Điểm cộng';}

$user=cds_user()??[];$isAdmin=($user['role']??'')==='admin';$isBgh=($user['role']??'')==='bgh'||in_array('bgh',(array)($user['groups']??[]),true);$isLeader=fc_is_leader($user);$canManage=$isAdmin||$isBgh||$isLeader;
$actorName=trim((string)($user['teacher_name']??$user['name']??''));$actorGroup=$actorName!==''?trim((string)get_teacher_group($actorName)):'';
$allTeachers=get_teachers_sorted();$managedTeachers=[];
foreach($allTeachers as $name)if($isAdmin||$isBgh||($isLeader&&$actorGroup!==''&&fc_norm(get_teacher_group($name))===fc_norm($actorGroup)))$managedTeachers[]=$name;
$criteria=array_values(array_filter(fc_criteria(),fn($criterion)=>($criterion['inspection_visible']??true)));$criteriaById=[];foreach($criteria as $criterion)$criteriaById[(string)$criterion['id']]=$criterion;
$dataFile=DATA_PATH.'/professional_file_checks.json';$records=load_json($dataFile,[]);if(!is_array($records))$records=[];
if(empty($_SESSION['fc_csrf']))$_SESSION['fc_csrf']=bin2hex(random_bytes(20));$csrf=$_SESSION['fc_csrf'];
$canSee=function(array $row)use($isAdmin,$isBgh,$isLeader,$actorGroup,$actorName){if($isAdmin||$isBgh)return true;if($isLeader&&$actorGroup!==''&&fc_norm($row['teacher_group']??'')===fc_norm($actorGroup))return true;return fc_norm($row['teacher_name']??'')===fc_norm($actorName);};

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Phiên làm việc không hợp lệ.');}
    $action=(string)($_POST['action']??'');
    if($action==='file_check_save'){
        if(!$canManage){http_response_code(403);exit('Chỉ tổ trưởng, BGH hoặc quản trị được cập nhật kiểm tra hồ sơ.');}
        $teacherName=trim((string)($_POST['teacher_name']??''));$date=trim((string)($_POST['date']??''));$content=trim((string)($_POST['content']??''));$result=trim((string)($_POST['result']??''));$contentType=($_POST['content_type']??'file')==='other'?'other':'file';$rating=trim((string)($_POST['rating']??''));$criterionId=trim((string)($_POST['criterion_id']??''));
        $validOutcome=$contentType==='file'?in_array($rating,['Tốt','Khá','Đạt','Chưa đạt'],true):isset($criteriaById[$criterionId]);
        if(!in_array($teacherName,$managedTeachers,true)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$content===''||$result===''||!$validOutcome){flash('Vui lòng nhập đầy đủ nội dung và chọn đúng xếp loại/tiêu chí.','danger');header('Location: '.BASE_URL.'kiemtrahoso.php');exit;}
        $criterion=$criteriaById[$criterionId]??[];$operation=$criterion['operation']??'add';$records[]=['id'=>'fc_'.bin2hex(random_bytes(8)),'teacher_id'=>fc_teacher_id($teacherName),'teacher_name'=>$teacherName,'teacher_group'=>trim((string)get_teacher_group($teacherName)),'inspector_id'=>$user['id']??'','inspector_name'=>$actorName,'date'=>$date,'content_type'=>$contentType,'content'=>$content,'result'=>$result,'rating'=>$contentType==='file'?$rating:($operation==='subtract'?'Điểm trừ':'Điểm cộng'),'criterion_id'=>$contentType==='other'?$criterionId:'','criterion_name'=>$contentType==='other'?($criterion['name']??''):'','operation'=>$contentType==='other'?$operation:'','points'=>$contentType==='other'?(float)($criterion['points']??0):0,'created_by'=>$user['id']??'','created_at'=>date('c'),'updated_at'=>date('c')];
        save_json($dataFile,array_values($records));flash('Đã lưu kết quả kiểm tra.');header('Location: '.BASE_URL.'kiemtrahoso.php');exit;
    }
    if($action==='file_check_delete'){
        if(!$isAdmin){http_response_code(403);exit('Chỉ quản trị được xóa kết quả kiểm tra.');}
        $id=trim((string)($_POST['id']??''));$records=array_values(array_filter($records,fn($row)=>($row['id']??'')!==$id));save_json($dataFile,$records);flash('Đã xóa kết quả kiểm tra.','warning');header('Location: '.BASE_URL.'kiemtrahoso.php');exit;
    }
}

$visible=array_values(array_filter($records,$canSee));usort($visible,fn($a,$b)=>strcmp(($b['date']??'').'|'.($b['created_at']??''),($a['date']??'').'|'.($a['created_at']??'')));
$view=($_GET['view']??'')==='stats'?'stats':'list';$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['from']??'')?(string)$_GET['from']:'';$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['to']??'')?(string)$_GET['to']:'';if($from&&$to&&$from>$to)[$from,$to]=[$to,$from];
$group=trim((string)($_GET['group']??''));$teacherFilter=trim((string)($_GET['teacher']??''));$inspector=trim((string)($_GET['inspector']??''));$ratingFilter=trim((string)($_GET['rating']??''));
$stats=array_values(array_filter($visible,fn($row)=>(!$from||($row['date']??'')>=$from)&&(!$to||($row['date']??'')<=$to)&&(!$group||($row['teacher_group']??'')===$group)&&(!$teacherFilter||($row['teacher_name']??'')===$teacherFilter)&&(!$inspector||($row['inspector_name']??'')===$inspector)&&(!$ratingFilter||fc_outcome($row,$criteriaById)===$ratingFilter)));
$groups=array_values(array_unique(array_filter(array_column($visible,'teacher_group'))));sort($groups,SORT_NATURAL|SORT_FLAG_CASE);$inspectors=array_values(array_unique(array_filter(array_column($visible,'inspector_name'))));sort($inspectors,SORT_NATURAL|SORT_FLAG_CASE);
$summary=[];foreach($stats as $row){$key=trim((string)($row['teacher_group']??''))?:'Chưa xếp tổ';if(!isset($summary[$key]))$summary[$key]=['total'=>0,'people'=>[],'Tốt'=>0,'Khá'=>0,'Đạt'=>0,'Chưa đạt'=>0];$summary[$key]['total']++;$summary[$key]['people'][$row['teacher_id']?:fc_norm($row['teacher_name'])]=true;$rating=$row['rating']??'';if(isset($summary[$key][$rating]))$summary[$key][$rating]++;}
require_once 'includes/header.php';
?>
<style>.fc-toolbar{display:flex;justify-content:space-between;gap:1rem;align-items:center;margin-bottom:1rem}.fc-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.85rem}.fc-form .wide{grid-column:span 2}.fc-table{min-width:1120px;table-layout:fixed}.fc-table th{text-align:center}.fc-table td{vertical-align:middle;overflow-wrap:anywhere}.fc-filter{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:.7rem;align-items:end}.fc-kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:.7rem}.fc-kpis>div{padding:1rem;text-align:center}.fc-kpis strong{display:block;font-size:1.55rem;color:var(--primary)}.fc-kpis span{font-size:.78rem;color:#64748b}.fc-summary{min-width:760px}.fc-summary th,.fc-summary td{text-align:center}.fc-summary td:nth-child(2){text-align:left}@media(max-width:767px){.fc-toolbar{align-items:flex-start;flex-direction:column}.fc-form,.fc-filter{grid-template-columns:1fr 1fr}.fc-form .wide{grid-column:1/-1}.fc-kpis{grid-template-columns:1fr 1fr}.fc-kpis>div:first-child{grid-column:1/-1}}</style>
