<?php if($view==='list'):?><?php if($canManage):?><section class="card mb-3"><div class="card-header">Ghi nhận kiểm tra</div><div class="card-body"><form method="post" id="check-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="file_check_save"><div class="fc-form"><div><label class="form-label fw-semibold">Giáo viên được kiểm tra</label><select class="form-select" name="teacher_name" required><option value="">Chọn giáo viên</option><?php foreach($managedTeachers as $name):?><option value="<?=e($name)?>"><?=e($name)?> · <?=e(get_teacher_group($name))?></option><?php endforeach;?></select></div><div><label class="form-label fw-semibold">Người kiểm tra</label><input class="form-control" value="<?=e($actorName)?>" disabled></div><div><label class="form-label fw-semibold">Ngày kiểm tra</label><input class="form-control" type="date" name="date" value="<?=date('Y-m-d')?>" required></div><div><label class="form-label fw-semibold">Loại nội dung</label><select class="form-select" name="content_type" id="content-type"><option value="file">Hồ sơ</option><option value="other">Nội dung khác</option></select></div><div class="wide"><label class="form-label fw-semibold">Nội dung kiểm tra</label><textarea class="form-control" name="content" rows="3" required></textarea></div><div id="file-rating"><label class="form-label fw-semibold">Xếp loại hồ sơ</label><select class="form-select" name="rating"><option value="">Chọn xếp loại</option><option>Tốt</option><option>Khá</option><option>Đạt</option><option>Chưa đạt</option></select></div><div id="other-criterion" class="wide d-none"><label class="form-label fw-semibold">Tiêu chí cộng/trừ điểm</label><select class="form-select" name="criterion_id"><option value="">Chọn theo Tiêu chí và thang điểm</option><?php foreach($criteria as $criterion):?><option value="<?=e($criterion['id'])?>"><?=($criterion['operation']??'add')==='subtract'?'− Trừ':'＋ Cộng'?> <?=e($criterion['points']??0)?> điểm · <?=e($criterion['name'])?></option><?php endforeach;?></select><div class="form-text">Quy định cộng/trừ và số điểm được lấy từ cấu hình đánh giá.</div></div><div class="wide"><label class="form-label fw-semibold">Kết quả kiểm tra</label><textarea class="form-control" name="result" rows="3" required></textarea></div></div><button class="btn btn-primary mt-3"><i class="bi bi-floppy"></i> Lưu kết quả</button></form></div></section><?php endif;?>
<section class="card"><div class="card-header d-flex justify-content-between"><span>Danh sách kiểm tra</span><span><?=count($visible)?> lượt</span></div><div class="table-responsive"><table class="table table-bordered table-hover mb-0 fc-table"><colgroup><col style="width:52px"><col style="width:175px"><col style="width:140px"><col style="width:175px"><col style="width:105px"><col style="width:105px"><col style="width:220px"><col style="width:245px"><col style="width:145px"><col style="width:70px"></colgroup><thead><tr><th>STT</th><th>Giáo viên</th><th>Tổ</th><th>Người kiểm tra</th><th>Ngày</th><th>Loại</th><th>Nội dung kiểm tra</th><th>Kết quả kiểm tra</th><th>Xếp loại/Điểm</th><th></th></tr></thead><tbody><?php foreach($visible as $i=>$row):$isFile=($row['content_type']??'file')==='file';$criterion=$criteriaById[(string)($row['criterion_id']??'')]??[];?><tr><td class="text-center"><?=$i+1?></td><td><strong><?=e($row['teacher_name']??'')?></strong></td><td><?=e($row['teacher_group']??'')?></td><td><?=e($row['inspector_name']??'')?></td><td class="text-center"><?=!empty($row['date'])?date('d/m/Y',strtotime($row['date'])):''?></td><td class="text-center"><?= $isFile?'Hồ sơ':'Khác' ?></td><td><?=nl2br(e($row['content']??''))?></td><td><?=nl2br(e($row['result']??''))?></td><td class="text-center"><?php if($isFile):?><span class="badge <?=($row['rating']??'')==='Tốt'?'bg-success':(($row['rating']??'')==='Khá'?'bg-info text-dark':(($row['rating']??'')==='Đạt'?'bg-warning text-dark':'bg-danger'))?>"><?=e($row['rating']??'')?></span><?php else:$operation=$criterion['operation']??$row['operation']??'add';$points=$criterion['points']??$row['points']??0;?><span class="badge <?=$operation==='subtract'?'bg-danger':'bg-success'?>"><?=$operation==='subtract'?'−':'＋'?><?=e($points)?> điểm</span><small class="d-block mt-1"><?=e($criterion['name']??$row['criterion_name']??'Tiêu chí đã xóa')?></small><?php endif;?></td><td class="text-center"><?php if($isAdmin):?><form method="post" onsubmit="return confirm('Xóa kết quả kiểm tra này?')"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="file_check_delete"><input type="hidden" name="id" value="<?=e($row['id']??'')?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form><?php endif;?></td></tr><?php endforeach;if(!$visible):?><tr><td colspan="10" class="text-center text-muted py-4">Chưa có dữ liệu kiểm tra.</td></tr><?php endif;?></tbody></table></div></section>
<?php else:?><form class="card mb-3" method="get"><input type="hidden" name="view" value="stats"><div class="card-body fc-filter"><div><label class="form-label fw-semibold">Từ ngày</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div><label class="form-label fw-semibold">Đến ngày</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div><label class="form-label fw-semibold">Tổ chuyên môn</label><select class="form-select" name="group"><option value="">Tất cả tổ</option><?php foreach($groups as $item):?><option <?=$item===$group?'selected':''?>><?=e($item)?></option><?php endforeach;?></select></div><div><label class="form-label fw-semibold">Giáo viên</label><select class="form-select" name="teacher"><option value="">Tất cả giáo viên</option><?php foreach($allTeachers as $name):?><option <?=$name===$teacherFilter?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></div><div><label class="form-label fw-semibold">Người kiểm tra</label><select class="form-select" name="inspector"><option value="">Tất cả</option><?php foreach($inspectors as $name):?><option <?=$name===$inspector?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></div><div><label class="form-label fw-semibold">Xếp loại</label><select class="form-select" name="rating"><option value="">Tất cả</option><?php foreach(['Tốt','Khá','Đạt','Chưa đạt'] as $item):?><option <?=$item===$ratingFilter?'selected':''?>><?=$item?></option><?php endforeach;?></select></div><button class="btn btn-primary"><i class="bi bi-funnel"></i> Áp dụng</button><a class="btn btn-outline-secondary" href="<?=BASE_URL?>kiemtrahoso.php?view=stats">Xóa lọc</a></div></form><div class="fc-kpis mb-3"><div class="card"><strong><?=count($stats)?></strong><span>Tổng lượt kiểm tra</span></div><?php foreach(['Tốt','Khá','Đạt','Chưa đạt'] as $item):?><div class="card"><strong><?=count(array_filter($stats,fn($row)=>($row['rating']??'')===$item))?></strong><span><?=$item?></span></div><?php endforeach;?></div><section class="card mb-3"><div class="card-header">Tổng hợp theo tổ</div><div class="table-responsive"><table class="table table-bordered mb-0 fc-summary"><thead><tr><th>STT</th><th>Tổ chuyên môn</th><th>Số giáo viên</th><th>Lượt kiểm tra</th><th>Tốt</th><th>Khá</th><th>Đạt</th><th>Chưa đạt</th></tr></thead><tbody><?php $i=0;foreach($summary as $name=>$row):?><tr><td><?=++$i?></td><td><strong><?=e($name)?></strong></td><td><?=count($row['people'])?></td><td><?=$row['total']?></td><td><?=$row['Tốt']?></td><td><?=$row['Khá']?></td><td><?=$row['Đạt']?></td><td><?=$row['Chưa đạt']?></td></tr><?php endforeach;if(!$summary):?><tr><td colspan="8" class="text-center text-muted py-4">Chưa có dữ liệu trong phạm vi lọc.</td></tr><?php endif;?></tbody></table></div></section><section class="card"><div class="card-header">Bảng kê chi tiết</div><div class="table-responsive"><table class="table table-bordered mb-0 fc-table"><thead><tr><th>STT</th><th>Giáo viên</th><th>Tổ</th><th>Người kiểm tra</th><th>Ngày</th><th>Nội dung</th><th>Kết quả</th><th>Xếp loại</th></tr></thead><tbody><?php foreach($stats as $i=>$row):?><tr><td class="text-center"><?=$i+1?></td><td><?=e($row['teacher_name']??'')?></td><td><?=e($row['teacher_group']??'')?></td><td><?=e($row['inspector_name']??'')?></td><td class="text-center"><?=date('d/m/Y',strtotime($row['date']))?></td><td><?=e($row['content']??'')?></td><td><?=e($row['result']??'')?></td><td class="text-center"><?=e($row['rating']??'')?></td></tr><?php endforeach;if(!$stats):?><tr><td colspan="8" class="text-center text-muted py-4">Chưa có dữ liệu.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?>
<?php if($view==='list'&&$canManage):?><script>(()=>{const type=document.getElementById('content-type'),file=document.getElementById('file-rating'),other=document.getElementById('other-criterion'),rating=file.querySelector('select'),criterion=other.querySelector('select');function sync(){const isFile=type.value==='file';file.classList.toggle('d-none',!isFile);other.classList.toggle('d-none',isFile);rating.required=isFile;criterion.required=!isFile;if(isFile)criterion.value='';else rating.value=''}type.addEventListener('change',sync);sync()})();</script><?php endif;?>
